Q: What can the __COUNTER__ pre-processor macro be used for? A: <p><code>__COUNTER__</code> is very useful when you are encrypting strings in runtime and you want every string to have a unique key, without storing a counter somewhere for the key of your encryption you can use Counter to be sure that every string has its own unique key!</p>
<p>I use it in my <code>XorString</code> 1 header library which decrypts strings in run-time, so if any hackers/crackers try to look at my binary file they won't find the strings there, but when the program runs every string is decrypted and shown as normal.</p>
<pre><code>#pragma once
#include &lt;string&gt;
#include &lt;array&gt;
#include &lt;cstdarg&gt;

#define BEGIN_NAMESPACE( x ) namespace x {
#define END_NAMESPACE }

BEGIN_NAMESPACE(XorCompileTime)

constexpr auto time = __TIME__;
constexpr auto seed = static_cast&lt; int &gt;(time[7]) + static_cast&lt; int &gt;(time[6]) * 10 + static_cast&lt; int &gt;(time[4]) * 60 + static_cast&lt; int &gt;(time[3]) * 600 + static_cast&lt; int &gt;(time[1]) * 3600 + static_cast&lt; int &gt;(time[0]) * 36000;

// 1988, Stephen Park and Keith Miller
// &quot;Random Number Generators: Good Ones Are Hard To Find&quot;, considered as &quot;minimal standard&quot;
// Park-Miller 31 bit pseudo-random number generator, implemented with G. Carta's optimisation:
// with 32-bit math and without division

template &lt; int N &gt;
struct RandomGenerator
{
private:
    static constexpr unsigned a = 16807; // 7^5
    static constexpr unsigned m = 2147483647; // 2^31 - 1

    static constexpr unsigned s = RandomGenerator&lt; N - 1 &gt;::value;
    static constexpr unsigned lo = a * (s &amp; 0xFFFF); // Multiply lower 16 bits by 16807
    static constexpr unsigned hi = a * (s &gt;&gt; 16); // Multiply higher 16 bits by 16807
    static constexpr unsigned lo2 = lo + ((hi &amp; 0x7FFF) &lt;&lt; 16); // Combine lower 15 bits of hi with lo's upper bits
    static constexpr unsigned hi2 = hi &gt;&gt; 15; // Discard lower 15 bits of hi
    static constexpr unsigned lo3 = lo2 + hi;

public:
    static constexpr unsigned max = m;
    static constexpr unsigned value = lo3 &gt; m ? lo3 - m : lo3;
};

template &lt;&gt;
struct RandomGenerator&lt; 0 &gt;
{
    static constexpr unsigned value = seed;
};

template &lt; int N, int M &gt;
struct RandomInt
{
    static constexpr auto value = RandomGenerator&lt; N + 1 &gt;::value % M;
};

template &lt; int N &gt;
struct RandomChar
{
    static const char value = static_cast&lt; char &gt;(1 + RandomInt&lt; N, 0x7F - 1 &gt;::value);
};

template &lt; size_t N, int K, typename Char &gt;
struct XorString
{
private:
    const char _key;
    std::array&lt; Char, N + 1 &gt; _encrypted;

    constexpr Char enc(Char c) const
    {
        return c ^ _key;
    }

    Char dec(Char c) const
    {
        return c ^ _key;
    }

public:
    template &lt; size_t... Is &gt;
    constexpr __forceinline XorString(const Char* str, std::index_sequence&lt; Is... &gt;) : _key(RandomChar&lt; K &gt;::value), _encrypted{ enc(str[Is])... }
    {
    }

    __forceinline decltype(auto) decrypt(void)
    {
        for (size_t i = 0; i &lt; N; ++i) {
            _encrypted[i] = dec(_encrypted[i]);
        }
        _encrypted[N] = '\0';
        return _encrypted.data();
    }
};

//--------------------------------------------------------------------------------
//-- Note: XorStr will __NOT__ work directly with functions like printf.
//         To work with them you need a wrapper function that takes a const char*
//         as parameter and passes it to printf and alike.
//
//         The Microsoft Compiler/Linker is not working correctly with variadic 
//         templates!
//  
//         Use the functions below or use std::cout (and similar)!
//--------------------------------------------------------------------------------

static auto w_printf = [](const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vprintf_s(fmt, args);
    va_end(args);
};

static auto w_printf_s = [](const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vprintf_s(fmt, args);
    va_end(args);
};

static auto w_sprintf = [](char* buf, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsprintf(buf, fmt, args);
    va_end(args);
};

static auto w_sprintf_ret = [](char* buf, const char* fmt, ...) {
    int ret;
    va_list args;
    va_start(args, fmt);
    ret = vsprintf(buf, fmt, args);
    va_end(args);
    return ret;
};

static auto w_sprintf_s = [](char* buf, size_t buf_size, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsprintf_s(buf, buf_size, fmt, args);
    va_end(args);
};

static auto w_sprintf_s_ret = [](char* buf, size_t buf_size, const char* fmt, ...) {
    int ret;
    va_list args;
    va_start(args, fmt);
    ret = vsprintf_s(buf, buf_size, fmt, args);
    va_end(args);
    return ret;
};

//Old functions before I found out about wrapper functions.
//#define XorStr( s ) ( XorCompileTime::XorString&lt; sizeof(s)/sizeof(char) - 1, __COUNTER__, char &gt;( s, std::make_index_sequence&lt; sizeof(s)/sizeof(char) - 1&gt;() ).decrypt() )
//#define XorStrW( s ) ( XorCompileTime::XorString&lt; sizeof(s)/sizeof(wchar_t) - 1, __COUNTER__, wchar_t &gt;( s, std::make_index_sequence&lt; sizeof(s)/sizeof(wchar_t) - 1&gt;() ).decrypt() )

//Wrapper functions to work in all functions below
#define XorStr( s ) []{ constexpr XorCompileTime::XorString&lt; sizeof(s)/sizeof(char) - 1, __COUNTER__, char &gt; expr( s, std::make_index_sequence&lt; sizeof(s)/sizeof(char) - 1&gt;() ); return expr; }().decrypt()
#define XorStrW( s ) []{ constexpr XorCompileTime::XorString&lt; sizeof(s)/sizeof(wchar_t) - 1, __COUNTER__, wchar_t &gt; expr( s, std::make_index_sequence&lt; sizeof(s)/sizeof(wchar_t) - 1&gt;() ); return expr; }().decrypt()

END_NAMESPACE
</code></pre>

Q: problem in calling object.method.method, Javascript A: <p>It's called <a href="http://en.wikipedia.org/wiki/Method_chaining" rel="nofollow">method chaining</a>. Have the functions return this.</p>

<pre><code>   this.getBook = function(name){
        for(i=0;i&lt;this.books.length;i++) {
           if(this.books[i].bookTitle == name )          {
              this.flag = i;
           }
        }

        return this;
   }
</code></pre>

<p>then you can call another method on the return of <code>lib.getBook("Dummy XML")</code>....</p>
